Return a JSON object with this shape:
{
  "system_name": "string",
  "perspective": "review_context.perspective",
  "review_context": "same context with diagram_referents resolved to stable ids and claim evidence retained",
  "representation": { "kind": "image|mermaid|svg", "source_id": "filename or unknown", "version": "drawn or labeled version, or unknown", "commit": "commit if labeled, or unknown" },
  "inventory": {
    "components": [{"id": "kebab-id", "name": "", "type": "process", "replica_of": "canonical component id or null", "replica_evidence": "drawn scaling-group or managed-pair evidence, or empty"}],
    "external_actors": [{"id": "", "name": "", "type": "actor"}],
